GRANT EXECUTE ON FUNCTION public.can_access_course_target(uuid, uuid) TO authenticated;
REVOKE ALL ON FUNCTION public.is_edutech_admin() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.is_edutech_admin() TO authenticated;
NOTIFY pgrst, 'reload schema';
